using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CastleAdministrationTests
{
    static readonly EntityId Site=new("site:kofu"),Head=new("person:shingen"),Agent=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool employee=false,string? policy=null)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],employee?Agent.Value:Head.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:policy??CastleAdministration.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){var t=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>t);}}
    static CastellanInput Input(WorldSession s,CastellanAction a,EntityId? original=null,int days=30)=>new(new("request:castellan-test/"+s.Revision),a,Site,a==CastellanAction.Appoint?Agent:null,original,days);
    static EntityId Appoint(WorldSession s,int days=30){var i=Input(s,CastellanAction.Appoint,days:days);Good(s.ManageCastellan(i,s.PlayerControl,s.Revision));return i.Id;}
    [Fact]public void AppointmentDoesNotTransferAnyAssetsRelationsOrMilitary(){var s=Start();var a=s.DiagnosticSnapshot();Appoint(s);var b=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(a.Offices),ContractJson.Write(b.Offices));Assert.Equal(ContractJson.Write(a.LandRights),ContractJson.Write(b.LandRights));Assert.Equal(ContractJson.Write(a.ResourceLots),ContractJson.Write(b.ResourceLots));Assert.Equal(ContractJson.Write(a.ServiceBonds),ContractJson.Write(b.ServiceBonds));Assert.Equal(ContractJson.Write(a.Units),ContractJson.Write(b.Units));Assert.Equal(ContractJson.Write(a.Salary),ContractJson.Write(b.Salary));}
    [Fact]public void EmployeeGetsBoundedLocalAuthorityWithoutPoliticalHeadAuthority(){var s=Start(true);Assert.Null(s.CommunityEconomyView());Appoint(s);Assert.NotNull(s.CommunityEconomyView());Assert.Null(FactionStances.ResolveAuthority(s.DiagnosticSnapshot(),Agent,new("org:takeda"),s.Seconds,s.Revision));Assert.False(s.HouseTreasuryView()!.CanSetBudget);}
    [Fact]public void LimitsCannotResetByReappointment(){var s=Start(true);Appoint(s);Good(s.ManageCommunity(new(new("request:castellan-relief"),Site,EconomyAction.RelieveVillage,500),Agent,s.Revision));Appoint(s);Assert.Equal(ResultCode.NotAvailable,s.ManageCommunity(new(new("request:castellan-relief-again"),Site,EconomyAction.RelieveVillage,1),Agent,s.Revision).Code);}
    [Fact]public void EmployeeCannotChangeHouseBudget(){var s=Start(true);Appoint(s);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseTreasury(new(new("request:castellan-budget"),TreasuryAction.SetBudget,Site,Amount:500),Agent,s.Revision).Code);}
    [Fact]public void CustodyIsDatedOwnerSeparatedAndDoesNotMoveStock(){var s=Start(true);var id=Appoint(s);var a=s.DiagnosticSnapshot();Good(s.ManageCastellan(Input(s,CastellanAction.ReceiveStore,id),Agent,s.Revision));var b=s.DiagnosticSnapshot();var receipt=b.Castellan!.Entries.Last().Receipt!;Assert.Equal(new EntityId("org:takeda"),receipt.Owner);Assert.Equal(a.Communities!.Accounts.Single(x=>x.Site==Site).HouseRice,receipt.Rice);Assert.Equal(ContractJson.Write(a.Communities),ContractJson.Write(b.Communities));Assert.Equal(ContractJson.Write(a.ResourceLots),ContractJson.Write(b.ResourceLots));Assert.Equal(ContractJson.Write(a.Materials),ContractJson.Write(b.Materials));Assert.Equal(ContractJson.Write(a.Domains),ContractJson.Write(b.Domains));}
    [Fact]public void HeadCannotSignEmployeeCustodyReceipt(){var s=Start();var id=Appoint(s);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.ReceiveStore,id),Head,s.Revision).Code);}
    [Fact]public void ReplacementKeepsEarlierRecordsAndEndsEarlierAppointment(){var s=Start();var old=Appoint(s);var newer=Appoint(s);var cards=s.CastellanView()!.Appointments;Assert.False(cards.Single(c=>c.Id==old).CanRelease);Assert.True(cards.Single(c=>c.Id==newer).CanRelease);Assert.Equal(2,s.DiagnosticSnapshot().Castellan!.Entries.Length);}
    [Fact]public void ReleaseNeedsTheActualCurrentAppointment(){var s=Start();var old=Appoint(s);Appoint(s);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.Release,old),Head,s.Revision).Code);}
    [Fact]public void HeadReleasesOnlyAdministrativeScope(){var s=Start();var id=Appoint(s);var a=s.DiagnosticSnapshot();Good(s.ManageCastellan(Input(s,CastellanAction.Release,id),Head,s.Revision));Assert.False(s.CastellanView()!.Appointments.Single().CanRelease);Assert.Equal(ContractJson.Write(a.ServiceBonds),ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds));}
    [Fact]public void EmployeeCannotReleaseOwnAppointmentUsingHeadAuthority(){var s=Start(true);var id=Appoint(s);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.Release,id),Agent,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(31)]public void InvalidDurationIsRejectedAtomically(int days){var s=Start();var a=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.Appoint,days:days),Head,s.Revision).Code);Assert.Equal(a,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void RefusalNeverCreatesAnAppointment(){var s=Start();var w=s.DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Agent?c with{WillObey=false}:c).ToArray();s=new(w);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.Appoint),Head,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Castellan!.Entries);}
    [Fact]public void OldPolicyDoesNotGainOfficeByLoading(){var s=Start(policy:CastleHandover.Policy);Assert.Null(s.CastellanView());Assert.Null(s.DiagnosticSnapshot().Castellan);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.Appoint),Head,s.Revision).Code);}
    [Fact]public void IdempotenceAndPayloadConflict(){var s=Start();var i=Input(s,CastellanAction.Appoint);Good(s.ManageCastellan(i,Head,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageCastellan(i,Head,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCastellan(i with{Days=1},Head,s.Revision).Code);}
    [Fact]public void StaleAndWrongActorCannotMutate(){var s=Start();var i=Input(s,CastellanAction.Appoint);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(i,Agent,s.Revision).Code);Appoint(s);Assert.Equal(ResultCode.StateChanged,s.ManageCastellan(i with{Id=new("request:stale-office")},Head,0).Code);}
    [Fact]public void TamperedReceiptIsRejected(){var s=Start(true);var id=Appoint(s);Good(s.ManageCastellan(Input(s,CastellanAction.ReceiveStore,id),Agent,s.Revision));var w=s.DiagnosticSnapshot();var es=w.Castellan!.Entries.ToArray();es[^1]=es[^1] with{Receipt=es[^1].Receipt! with{Rice=999999}};w.Castellan=w.Castellan with{Entries=es};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ForgedAppointmentWithoutActualConsentRejected(){var s=Start();Appoint(s);var w=s.DiagnosticSnapshot();var e=w.Castellan!.Entries.Single();w.Castellan=w.Castellan with{Entries=[e with{Agent=Head}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ParallelStewardshipCannotOverrideCastellan(){var s=Start();Appoint(s);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(new(new("request:parallel-steward"),StewardAction.Assign,Site,Agent,ReturnAddress:Site),Head,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ActualGenerationRecoveryAndFutureEquality(int phase){var a=Start(phase is 1 or 2);var id=Appoint(a);if(phase is 1 or 2)Good(a.ManageCastellan(Input(a,CastellanAction.ReceiveStore,id),Agent,a.Revision));if(phase==2)Good(a.ManageCommunity(new(new("request:office-saved-relief"),Site,EconomyAction.RelieveVillage,10),Agent,a.Revision));if(phase==3)Good(a.ManageCastellan(Input(a,CastellanAction.Release,id),Head,a.Revision));a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"castellan-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"castellan",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("castellan"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CastellanView()),ContractJson.Write(b.CastellanView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"castellan-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"castellan-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var q in new[]{a,b})Advance(q,q.Seconds+10);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void OccupiedGateBlocksNewAdministrationButKeepsPastOrders(){var s=CastleHandoverTests.Start(policy:CastleAdministration.Policy);Appoint(s);Good(s.ManageCommunity(new(new("request:before-gate-relief"),Site,EconomyAction.RelieveVillage,1),Head,s.Revision));var id=new EntityId("request:office-gate");Good(s.ManageCastle(new(id,CastleAction.Offer,Site,RecipientOwner:new("org:oda")),Head,s.Revision));foreach(var action in new[]{CastleAction.Confirm,CastleAction.Gate})Good(s.ManageCastle(new(new("request:office-gate/"+action),action,Site,id),Head,s.Revision));Assert.True(CastleAdministration.Blocked(s.DiagnosticSnapshot(),Site,s.Seconds,s.Revision+1));Assert.Null(s.CommunityEconomyView());Assert.Null(s.HouseTreasuryView());Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.Appoint),Head,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCommunity(new(new("request:after-gate-relief"),Site,EconomyAction.RelieveVillage,1),Head,s.Revision).Code);var restored=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));Assert.Contains(restored.DiagnosticSnapshot().Communities!.Orders,o=>o.Input.Id.Value=="request:before-gate-relief");}
    [Fact]public void NpcCastellanActuallyUsesLocalAdministrationWithoutInvalidStewardPapers(){var s=Start();Appoint(s);Advance(s,86400);Assert.Contains(s.DiagnosticSnapshot().CommunityAdministration!.Decisions,d=>d.Site==Site&&d.Actor==Agent&&d.Action!=null);Assert.Empty(s.DiagnosticSnapshot().Stewardship!.Papers);new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void ExpiryDoesNotRestoreThePreviousAppointment(){var s=Start(true);Appoint(s);Appoint(s,1);Advance(s,86400);Assert.Null(s.CommunityEconomyView());Assert.DoesNotContain(s.CastellanView()!.Appointments,c=>c.CanReceive);Assert.Equal(2,s.DiagnosticSnapshot().Castellan!.Entries.Count(e=>e.Input.Action==CastellanAction.Appoint));}
    [Fact]public void PlayerCastellanIsNotAutoplayedAndLifeRoleMatchesOffice(){var s=Start(true);Appoint(s);Assert.Contains("期限付き",s.PersonalLifeView()!.Role);Advance(s,86400);Assert.DoesNotContain(s.DiagnosticSnapshot().CommunityAdministration!.Decisions,d=>d.Actor==Agent);}
    [Fact]public void ExistingStewardshipCannotBeOverlapped(){var s=Start();Good(s.ManageStewardship(new(new("request:prior-steward"),StewardAction.Assign,Site,Agent,ReturnAddress:Site),Head,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Input(s,CastellanAction.Appoint),Head,s.Revision).Code);}
    [Fact]public void ForeignPersonCannotBeAppointedThroughLocalPresenceAlone(){var s=CastleHandoverTests.Start(policy:CastleAdministration.Policy);var i=Input(s,CastellanAction.Appoint) with{Person=new("person:nobunaga")};Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(i,Head,s.Revision).Code);}

    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:castellan-trip/"+s.Revision,node),s.Revision));Advance(s,s.Seconds+2);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt+1);}
    [Fact]public void AppointedCastellanActuallyReceivesOutstandingHouseFreight(){var s=Start();var office=Appoint(s);var id=new EntityId("request:castellan-freight");Good(s.ManageHouseFreight(new(id,HouseFreightAction.Dispatch,Home:Site,Source:new("site:castle"),Commodity:"wood",Quantity:10,Advance:200),Head,s.Revision));Move(s,"castle");Good(s.ManageHouseFreight(new(new("request:castellan-buy"),HouseFreightAction.Buy,id),Head,s.Revision));Move(s,"kofu");Good(s.ManageHouseFreight(new HouseFreightInput(new("request:castellan-deliver"),HouseFreightAction.Receive,id){Receiver=Agent},Head,s.Revision));var receipt=s.HouseFreightView()!.Jobs.Single().Receipt!;Assert.Equal(Agent,receipt.Receiver);Assert.Equal(office,receipt.Grant);Assert.Equal(new EntityId("org:takeda"),receipt.Owner);Assert.Equal(10,receipt.Cargo);new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void TwoDifferentPeopleCanReplaceOfficeWithoutInheritingCustodyOrService(){var created=NewGameWorldTests.Officer("created:second-castellan",StartTemplate.Retainer,"site:kofu",Head.Value);var scenario=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var config=new WorldSetupRequest([created],[]);var preview=NewGameSetup.Preview(scenario,config);Assert.True(preview.IsEligible(),string.Join(',',preview.Errors));var world=NewGameSetup.Confirm(scenario,config,preview);var s=new WorldSession(NewGameWorld.Create(world,[created],Head.Value,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:CastleAdministration.Policy));var old=Appoint(s);var relations=ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds);var i=Input(s,CastellanAction.Appoint) with{Person=new(created.Id)};Good(s.ManageCastellan(i,Head,s.Revision));Assert.False(s.CastellanView()!.Appointments.Single(c=>c.Id==old).CanRelease);Assert.True(s.CastellanView()!.Appointments.Single(c=>c.Person.Value==created.Id).CanRelease);Assert.Equal(relations,ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds));}

}
